INSERT INTO "Notice" (id, "schoolId", "creatorId", title, category, "sourceText", "sourceLanguage", "simplifiedText", "simplifiedBy", priority, "workflowStatus", version, "targetLanguages", channels, "recipientMode", "selectedGuardianIds", "scheduledAt", "approvedById", "approvedAt", "rejectionReason", "dispatchedAt", "attachmentPath", "attachmentMime", "attachmentName", "createdAt", "updatedAt") VALUES
	('cmvifoo4f00mj7dnnu7hxisl0', 'cmvifoncn00007dnns9v38so6', 'cmvifoo2100ls7dnnkt3rtjg0', 'Parent-Teacher Meeting on 25 October', 'PTM', 'Parent-Teacher Meeting will be held on 25 October 2026 at 11:00 AM in the school premises. All parents are requested to attend the meeting and bring the student''s report card. For any queries, please contact the class teacher.', 'en', 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'simulated:curated-sample', 'HIGH', 'DISPATCHED', 2, 'gu,hi,en', 'whatsapp,sms,voice', 'CLASS', '[]', NULL, 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-11 04:30:00.385', NULL, '2026-10-14 04:30:00', NULL, NULL, NULL, '2026-10-11 04:30:00', '2026-10-21 18:16:39.483'),
	('cmvifoomq00t37dnn1k46dolq', 'cmvifoncn00007dnns9v38so6', 'cmvifoo2400lu7dnnfzqbagpd', 'Scholarship forms due 31 October', 'SCHOLARSHIP', 'Scholarship forms for eligible students of Class 9 must be submitted at the school office on or before 31 October 2026. Please bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship amount is ₹5,000 per year. For help, call the school office at 90000 00001.', 'en', 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', 'simulated:curated-sample', 'NORMAL', 'DISPATCHED', 2, 'gu,hi,en', 'whatsapp,sms', 'CLASS', '[]', NULL, 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-04 04:30:00.173', NULL, '2026-10-07 04:30:00', NULL, NULL, NULL, '2026-10-04 04:30:00', '2026-10-21 18:16:39.855'),
	('cmvifoovj00yk7dnnarijnb7r', 'cmvifoncn00007dnns9v38so6', 'cmvifoo2500lw7dnn42cz5uxg', 'Diwali vacation dates', 'HOLIDAY', 'The school will remain closed from 9 November 2026 to 22 November 2026 for the Diwali vacation. Classes will resume on 23 November 2026.', 'en', 'School is closed for the Diwali vacation from 9 November 2026 to 22 November 2026. School opens again on 23 November 2026.', 'simulated:curated-sample', 'NORMAL', 'DISPATCHED', 2, 'gu,hi,en', 'whatsapp,sms', 'CLASS', '[]', NULL, 'cmvifoo2500lw7dnn42cz5uxg', '2026-09-28 04:30:00.107', NULL, '2026-10-01 04:30:00', NULL, NULL, NULL, '2026-09-28 04:30:00', '2026-10-21 18:16:40.368'),
	('cmvifoplq01dt7dnnw6wkoh29', 'cmvifoncn00007dnns9v38so6', 'cmvifoo2100ls7dnnkt3rtjg0', 'PTM reminder for 5-B (check Gujarati date)', 'PTM', 'Parent-Teacher Meeting will be held on 25 October 2026 at 11:00 AM in the school premises. All parents are requested to attend the meeting and bring the student''s report card. For any queries, please contact the class teacher.', 'en', 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'simulated:curated-sample', 'HIGH', 'PENDING_APPROVAL', 2, 'gu,hi,en', 'whatsapp,sms', 'CLASS', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-17 04:30:00', '2026-10-21 18:16:41.078'),
	('cmvifoph201as7dnn9n8hnbb7', 'cmvifoncn00007dnns9v38so6', 'cmvifoo2500lw7dnn42cz5uxg', 'Half-yearly examination timetable', 'EXAMINATION', 'The half-yearly examination for Classes 6 to 8 will begin on 3 November 2026. Examinations will start at 10:30 AM every day. Students must carry their hall ticket and arrive at school 15 minutes before the examination.', 'en', 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', 'simulated:curated-sample', 'NORMAL', 'APPROVED', 2, 'gu,hi,en', 'whatsapp,sms', 'CLASS', '[]', NULL, 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-17 04:30:00.144', NULL, NULL, NULL, NULL, NULL, '2026-10-17 04:30:00', '2026-10-21 18:16:40.845'),
	('cmvifopxo01nu7dnnuyth1wip', 'cmvifoncs00017dnnpk6imiyg', 'cmvifoo2q00m57dnnzexuicmw', 'Half-yearly examination timetable', 'EXAMINATION', 'The half-yearly examination for Classes 6 to 8 will begin on 3 November 2026. Examinations will start at 10:30 AM every day. Students must carry their hall ticket and arrive at school 15 minutes before the examination.', 'en', 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', 'simulated:curated-sample', 'NORMAL', 'DISPATCHED', 2, 'gu,hi,en', 'whatsapp,sms', 'CLASS', '[]', NULL, 'cmvifoo2q00m57dnnzexuicmw', '2026-10-05 04:30:00.128', NULL, '2026-10-08 04:30:00', NULL, NULL, NULL, '2026-10-05 04:30:00', '2026-10-21 18:16:41.568'),
