INSERT INTO "NoticeTranslation" (id, "noticeId", language, "translatedText", "generatedText", "editedText", provider, model, "validationStatus", "reviewState", version, "sourceVersion", "createdAt", "updatedAt") VALUES
	('cmvifoo6k00nc7dnn2y5a6hcm', 'cmvifoo4f00mj7dnnu7hxisl0', 'en', 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:39.02', '2026-10-21 18:16:39.209'),
	('cmvifoo5e00ms7dnnfixb6dsh', 'cmvifoo4f00mj7dnnu7hxisl0', 'gu', 'વાલી-શિક્ષક બેઠક ૨૫ ઓક્ટોબર ૨૦૨૬ ના રોજ સવારે ૧૧:૦૦ વાગ્યે યોજાશે. બેઠક શાળાના પરિસરમાં થશે. કૃપા કરીને બેઠકમાં હાજર રહો. તમારા બાળકનું રિપોર્ટ કાર્ડ સાથે લાવવું. કોઈ પ્રશ્ન હોય તો વર્ગ શિક્ષકનો સંપર્ક કરો.', 'વાલી-શિક્ષક બેઠક ૨૫ ઓક્ટોબર ૨૦૨૬ ના રોજ સવારે ૧૧:૦૦ વાગ્યે યોજાશે. બેઠક શાળાના પરિસરમાં થશે. કૃપા કરીને બેઠકમાં હાજર રહો. તમારા બાળકનું રિપોર્ટ કાર્ડ સાથે લાવવું. કોઈ પ્રશ્ન હોય તો વર્ગ શિક્ષકનો સંપર્ક કરો.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:38.979', '2026-10-21 18:16:39.285'),
	('cmvifoo5z00n27dnniekpl3ux', 'cmvifoo4f00mj7dnnu7hxisl0', 'hi', 'अभिभावक-शिक्षक बैठक 25 अक्टूबर 2026 को सुबह 11:00 बजे होगी। बैठक विद्यालय परिसर में होगी। कृपया बैठक में आएं। अपने बच्चे का रिपोर्ट कार्ड साथ लाएं। कोई सवाल हो तो कक्षा शिक्षक से संपर्क करें।', 'अभिभावक-शिक्षक बैठक 25 अक्टूबर 2026 को सुबह 11:00 बजे होगी। बैठक विद्यालय परिसर में होगी। कृपया बैठक में आएं। अपने बच्चे का रिपोर्ट कार्ड साथ लाएं। कोई सवाल हो तो कक्षा शिक्षक से संपर्क करें।', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:38.999', '2026-10-21 18:16:39.297'),
	('cmvifoook00tw7dnn391lsllu', 'cmvifoomq00t37dnn1k46dolq', 'en', 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:39.669', '2026-10-21 18:16:39.72'),
	('cmvifosy903mm7dnnvt3vnz5h', 'cmvifoswp03lt7dnnagus17b1', 'en', 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:45.201', '2026-10-21 18:16:45.233'),
	('cmvifosxg03m27dnng6428j1f', 'cmvifoswp03lt7dnnagus17b1', 'gu', 'ધોરણ ૬ થી ૮ ની છમાસિક પરીક્ષા ૩ નવેમ્બર ૨૦૨૬ થી શરૂ થશે. દરરોજ પરીક્ષા સવારે ૧૦:૩૦ વાગ્યે શરૂ થશે. વિદ્યાર્થીઓએ હોલ ટિકિટ સાથે લાવવી. વિદ્યાર્થીઓ પરીક્ષાના ૧૫ મિનિટ પહેલાં શાળામાં આવો.', 'ધોરણ ૬ થી ૮ ની છમાસિક પરીક્ષા ૩ નવેમ્બર ૨૦૨૬ થી શરૂ થશે. દરરોજ પરીક્ષા સવારે ૧૦:૩૦ વાગ્યે શરૂ થશે. વિદ્યાર્થીઓએ હોલ ટિકિટ સાથે લાવવી. વિદ્યાર્થીઓ પરીક્ષાના ૧૫ મિનિટ પહેલાં શાળામાં આવો.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:45.172', '2026-10-21 18:16:45.242'),
	('cmvifosxu03mc7dnnwxlnca5s', 'cmvifoswp03lt7dnnagus17b1', 'hi', 'कक्षा 6 से 8 की अर्धवार्षिक परीक्षा 3 नवंबर 2026 से शुरू होगी। हर दिन परीक्षा सुबह 10:30 बजे शुरू होगी। विद्यार्थी अपना प्रवेश पत्र साथ लाएं। विद्यार्थी परीक्षा से 15 मिनट पहले विद्यालय में आएं।', 'कक्षा 6 से 8 की अर्धवार्षिक परीक्षा 3 नवंबर 2026 से शुरू होगी। हर दिन परीक्षा सुबह 10:30 बजे शुरू होगी। विद्यार्थी अपना प्रवेश पत्र साथ लाएं। विद्यार्थी परीक्षा से 15 मिनट पहले विद्यालय में आएं।', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:45.187', '2026-10-21 18:16:45.251'),
	('cmvifoonf00tc7dnn6r5kb3fr', 'cmvifoomq00t37dnn1k46dolq', 'gu', 'ધોરણ ૯ ના પાત્ર વિદ્યાર્થીઓ શિષ્યવૃત્તિ માટે અરજી કરી શકે છે. ફોર્મ ૩૧ ઓક્ટોબર ૨૦૨૬ સુધીમાં શાળા કાર્યાલયમાં જમા કરાવો. વિદ્યાર્થીનું આધાર કાર્ડ, બેંક પાસબુક અને આવકનો દાખલો સાથે લાવો. શિષ્યવૃત્તિ દર વર્ષે ₹૫,૦૦૦ છે. મદદ માટે શાળા કાર્યાલયને ૯૦૦૦૦ ૦૦૦૦૧ પર ફોન કરો.', 'ધોરણ ૯ ના પાત્ર વિદ્યાર્થીઓ શિષ્યવૃત્તિ માટે અરજી કરી શકે છે. ફોર્મ ૩૧ ઓક્ટોબર ૨૦૨૬ સુધીમાં શાળા કાર્યાલયમાં જમા કરાવો. વિદ્યાર્થીનું આધાર કાર્ડ, બેંક પાસબુક અને આવકનો દાખલો સાથે લાવો. શિષ્યવૃત્તિ દર વર્ષે ₹૫,૦૦૦ છે. મદદ માટે શાળા કાર્યાલયને ૯૦૦૦૦ ૦૦૦૦૧ પર ફોન કરો.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:39.627', '2026-10-21 18:16:39.738'),
	('cmvifooo000tm7dnnhy0a7jxq', 'cmvifoomq00t37dnn1k46dolq', 'hi', 'कक्षा 9 के पात्र विद्यार्थी छात्रवृत्ति के लिए आवेदन कर सकते हैं। फॉर्म 31 अक्टूबर 2026 तक विद्यालय कार्यालय में जमा करें। विद्यार्थी का आधार कार्ड, बैंक पासबुक और आय प्रमाण पत्र साथ लाएं। छात्रवृत्ति ₹5,000 प्रति वर्ष है। मदद के लिए विद्यालय कार्यालय को 90000 00001 पर फ़ोन करें।', 'कक्षा 9 के पात्र विद्यार्थी छात्रवृत्ति के लिए आवेदन कर सकते हैं। फॉर्म 31 अक्टूबर 2026 तक विद्यालय कार्यालय में जमा करें। विद्यार्थी का आधार कार्ड, बैंक पासबुक और आय प्रमाण पत्र साथ लाएं। छात्रवृत्ति ₹5,000 प्रति वर्ष है। मदद के लिए विद्यालय कार्यालय को 90000 00001 पर फ़ोन करें।', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:39.648', '2026-10-21 18:16:39.755'),
