	('cmvifosp303gu7dnntcru9n1a', 'cmvifosoi03gl7dnnrch9kcfb', 'gu', 'વાલી-શિક્ષક બેઠક ૨૫ ઓક્ટોબર ૨૦૨૬ ના રોજ સવારે ૧૧:૦૦ વાગ્યે યોજાશે. બેઠક શાળાના પરિસરમાં થશે. કૃપા કરીને બેઠકમાં હાજર રહો. તમારા બાળકનું રિપોર્ટ કાર્ડ સાથે લાવવું. કોઈ પ્રશ્ન હોય તો વર્ગ શિક્ષકનો સંપર્ક કરો.', 'વાલી-શિક્ષક બેઠક ૨૫ ઓક્ટોબર ૨૦૨૬ ના રોજ સવારે ૧૧:૦૦ વાગ્યે યોજાશે. બેઠક શાળાના પરિસરમાં થશે. કૃપા કરીને બેઠકમાં હાજર રહો. તમારા બાળકનું રિપોર્ટ કાર્ડ સાથે લાવવું. કોઈ પ્રશ્ન હોય તો વર્ગ શિક્ષકનો સંપર્ક કરો.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:44.872', '2026-10-21 18:16:44.95'),
