	('cmvifoutn04z67dnnq59vcmi1', 'cmvifous804yd7dnnogw007rz', 'en', 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:47.627', '2026-10-21 18:16:47.661'),
