	('cmvifout904yw7dnn6pnmmw5m', 'cmvifous804yd7dnnogw007rz', 'hi', 'कक्षा 6 से 8 की अर्धवार्षिक परीक्षा 3 नवंबर 2026 से शुरू होगी। हर दिन परीक्षा सुबह 10:30 बजे शुरू होगी। विद्यार्थी अपना प्रवेश पत्र साथ लाएं। विद्यार्थी परीक्षा से 15 मिनट पहले विद्यालय में आएं।', 'कक्षा 6 से 8 की अर्धवार्षिक परीक्षा 3 नवंबर 2026 से शुरू होगी। हर दिन परीक्षा सुबह 10:30 बजे शुरू होगी। विद्यार्थी अपना प्रवेश पत्र साथ लाएं। विद्यार्थी परीक्षा से 15 मिनट पहले विद्यालय में आएं।', NULL, 'demo', NULL, 'PASSED', 'OPEN', 1, 2, '2026-10-21 18:16:47.613', '2026-10-21 18:16:47.68');
