	('cmvifoo6a00n87dnn8vq2uqdr', 'cmvifoo4f00mj7dnnu7hxisl0', 'cmvifoo5z00n27dnniekpl3ux', 'hi', 'demo-sample', 'espeak-ng hi', 'demo-audio/ptm-hi.mp3', 'audio/mpeg', 21.6, 'READY', 1, 'अभिभावक-शिक्षक बैठक 25 अक्टूबर 2026 को सुबह 11:00 बजे होगी। बैठक विद्यालय परिसर में होगी। कृपया बैठक में आएं। अपने बच्चे का रिपोर्ट कार्ड साथ लाएं। कोई सवाल हो तो कक्षा शिक्षक से संपर्क करें।', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.01'),
	('cmvifoo6t00ni7dnnd7m4v3qq', 'cmvifoo4f00mj7dnnu7hxisl0', 'cmvifoo6k00nc7dnn2y5a6hcm', 'en', 'demo-sample', 'espeak-ng en-us', 'demo-audio/ptm-en.mp3', 'audio/mpeg', 20, 'READY', 1, 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.028'),
	('cmvifoono00ti7dnnwbzpdgip', 'cmvifoomq00t37dnn1k46dolq', 'cmvifoonf00tc7dnn6r5kb3fr', 'gu', 'demo-sample', 'espeak-ng gu', 'demo-audio/scholarship-gu.mp3', 'audio/mpeg', 30.2, 'READY', 1, 'ધોરણ ૯ ના પાત્ર વિદ્યાર્થીઓ શિષ્યવૃત્તિ માટે અરજી કરી શકે છે. ફોર્મ ૩૧ ઓક્ટોબર ૨૦૨૬ સુધીમાં શાળા કાર્યાલયમાં જમા કરાવો. વિદ્યાર્થીનું આધાર કાર્ડ, બેંક પાસબુક અને આવકનો દાખલો સાથે લાવો. શિષ્યવૃત્તિ દર વર્ષે ₹૫,૦૦૦ છે. મદદ માટે શાળા કાર્યાલયને ૯૦૦૦૦ ૦૦૦૦૧ પર ફોન કરો.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.636'),
	('cmvifoooc00ts7dnnx0vpblt9', 'cmvifoomq00t37dnn1k46dolq', 'cmvifooo000tm7dnnhy0a7jxq', 'hi', 'demo-sample', 'espeak-ng hi', 'demo-audio/scholarship-hi.mp3', 'audio/mpeg', 28.3, 'READY', 1, 'कक्षा 9 के पात्र विद्यार्थी छात्रवृत्ति के लिए आवेदन कर सकते हैं। फॉर्म 31 अक्टूबर 2026 तक विद्यालय कार्यालय में जमा करें। विद्यार्थी का आधार कार्ड, बैंक पासबुक और आय प्रमाण पत्र साथ लाएं। छात्रवृत्ति ₹5,000 प्रति वर्ष है। मदद के लिए विद्यालय कार्यालय को 90000 00001 पर फ़ोन करें।', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.659'),
	('cmvifooov00u27dnn51hrhnhq', 'cmvifoomq00t37dnn1k46dolq', 'cmvifoook00tw7dnn391lsllu', 'en', 'demo-sample', 'espeak-ng en-us', 'demo-audio/scholarship-en.mp3', 'audio/mpeg', 26.1, 'READY', 1, 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.678'),
	('cmvifoowd00yz7dnnnzlvuo9w', 'cmvifoovj00yk7dnnarijnb7r', 'cmvifoow500yt7dnnnpwqvydn', 'gu', 'demo-sample', 'espeak-ng gu', 'demo-audio/holiday-gu.mp3', 'audio/mpeg', 15, 'READY', 1, 'દિવાળી વેકેશન માટે શાળા ૯ નવેમ્બર ૨૦૨૬ થી ૨૨ નવેમ્બર ૨૦૨૬ સુધી બંધ રહેશે. શાળા ૨૩ નવેમ્બર ૨૦૨૬ ના રોજ ફરી શરૂ થશે.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.949'),
	('cmvifoowr00z97dnn9i1wnfsy', 'cmvifoovj00yk7dnnarijnb7r', 'cmvifoowj00z37dnn6gkgsaba', 'hi', 'demo-sample', 'espeak-ng hi', 'demo-audio/holiday-hi.mp3', 'audio/mpeg', 14.1, 'READY', 1, 'दीवाली अवकाश के लिए विद्यालय 9 नवंबर 2026 से 22 नवंबर 2026 तक बंद रहेगा। विद्यालय 23 नवंबर 2026 को फिर से खुलेगा।', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.962'),
	('cmvifoox400zj7dnnu5pli7ut', 'cmvifoovj00yk7dnnarijnb7r', 'cmvifoowx00zd7dnnxcn1vjcm', 'en', 'demo-sample', 'espeak-ng en-us', 'demo-audio/holiday-en.mp3', 'audio/mpeg', 15.2, 'READY', 1, 'School is closed for the Diwali vacation from 9 November 2026 to 22 November 2026. School opens again on 23 November 2026.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:39.976'),
	('cmvifophy01b77dnnfjfc6k8l', 'cmvifoph201as7dnn9n8hnbb7', 'cmvifophr01b17dnne0daacjh', 'gu', 'demo-sample', 'espeak-ng gu', 'demo-audio/exam-gu.mp3', 'audio/mpeg', 19.9, 'READY', 1, 'ધોરણ ૬ થી ૮ ની છમાસિક પરીક્ષા ૩ નવેમ્બર ૨૦૨૬ થી શરૂ થશે. દરરોજ પરીક્ષા સવારે ૧૦:૩૦ વાગ્યે શરૂ થશે. વિદ્યાર્થીઓએ હોલ ટિકિટ સાથે લાવવી. વિદ્યાર્થીઓ પરીક્ષાના ૧૫ મિનિટ પહેલાં શાળામાં આવો.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:40.726'),
