	('cmvifosi503bx7dnni5ab3n7z', 'cmvifosh303b87dnnqgpwmyrz', 'cmvifoshy03br7dnnqssm0pjv', 'hi', 'demo-sample', 'espeak-ng hi', 'demo-audio/exam-hi.mp3', 'audio/mpeg', 19.8, 'READY', 1, 'कक्षा 6 से 8 की अर्धवार्षिक परीक्षा 3 नवंबर 2026 से शुरू होगी। हर दिन परीक्षा सुबह 10:30 बजे शुरू होगी। विद्यार्थी अपना प्रवेश पत्र साथ लाएं। विद्यार्थी परीक्षा से 15 मिनट पहले विद्यालय में आएं।', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:44.62'),
