	('cmvifot7y03tu7dnn1nofs7jn', 'cmvifot6i03sv7dnnnjyq81bk', 'cmvifot7r03to7dnncucbvnng', 'en', 'demo-sample', 'espeak-ng en-us', 'demo-audio/ptm-en.mp3', 'audio/mpeg', 20, 'READY', 1, 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:45.549'),
	('cmvifoth7040d7dnn5kwlfsm0', 'cmvifotge03zy7dnng5oybjrr', 'cmvifotgz04077dnnjtfrwpgp', 'gu', 'demo-sample', 'espeak-ng gu', 'demo-audio/scholarship-gu.mp3', 'audio/mpeg', 30.2, 'READY', 1, 'ધોરણ ૯ ના પાત્ર વિદ્યાર્થીઓ શિષ્યવૃત્તિ માટે અરજી કરી શકે છે. ફોર્મ ૩૧ ઓક્ટોબર ૨૦૨૬ સુધીમાં શાળા કાર્યાલયમાં જમા કરાવો. વિદ્યાર્થીનું આધાર કાર્ડ, બેંક પાસબુક અને આવકનો દાખલો સાથે લાવો. શિષ્યવૃત્તિ દર વર્ષે ₹૫,૦૦૦ છે. મદદ માટે શાળા કાર્યાલયને ૯૦૦૦૦ ૦૦૦૦૧ પર ફોન કરો.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:45.882'),
	('cmvifothm040n7dnn5eruuoz0', 'cmvifotge03zy7dnng5oybjrr', 'cmvifothe040h7dnntyban7a3', 'hi', 'demo-sample', 'espeak-ng hi', 'demo-audio/scholarship-hi.mp3', 'audio/mpeg', 28.3, 'READY', 1, 'कक्षा 9 के पात्र विद्यार्थी छात्रवृत्ति के लिए आवेदन कर सकते हैं। फॉर्म 31 अक्टूबर 2026 तक विद्यालय कार्यालय में जमा करें। विद्यार्थी का आधार कार्ड, बैंक पासबुक और आय प्रमाण पत्र साथ लाएं। छात्रवृत्ति ₹5,000 प्रति वर्ष है। मदद के लिए विद्यालय कार्यालय को 90000 00001 पर फ़ोन करें।', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:45.897'),
	('cmvifothy040x7dnn9gqm4cad', 'cmvifotge03zy7dnng5oybjrr', 'cmvifoths040r7dnnmiutxsxb', 'en', 'demo-sample', 'espeak-ng en-us', 'demo-audio/scholarship-en.mp3', 'audio/mpeg', 26.1, 'READY', 1, 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:45.91'),
	('cmvifotnv045i7dnn51710ry6', 'cmvifotn204537dnnwfhpysk4', 'cmvifotno045c7dnnc0t56llr', 'gu', 'demo-sample', 'espeak-ng gu', 'demo-audio/holiday-gu.mp3', 'audio/mpeg', 15, 'READY', 1, 'દિવાળી વેકેશન માટે શાળા ૯ નવેમ્બર ૨૦૨૬ થી ૨૨ નવેમ્બર ૨૦૨૬ સુધી બંધ રહેશે. શાળા ૨૩ નવેમ્બર ૨૦૨૬ ના રોજ ફરી શરૂ થશે.', 'Pre-generated sample recording (eSpeak NG, open-source synthetic voice).', '2026-10-21 18:16:46.122'),
