INSERT INTO "NoticeVersion" (id, "noticeId", version, title, "sourceText", "simplifiedText", "createdById", "createdAt") VALUES
	('cmvifoo4f00mk7dnnkbgqktb2', 'cmvifoo4f00mj7dnnu7hxisl0', 1, 'Parent-Teacher Meeting on 25 October', 'Parent-Teacher Meeting will be held on 25 October 2026 at 11:00 AM in the school premises. All parents are requested to attend the meeting and bring the student''s report card. For any queries, please contact the class teacher.', NULL, 'cmvifoo2100ls7dnnkt3rtjg0', '2026-10-11 04:30:00'),
	('cmvifoo5300mo7dnn1gb1fs9r', 'cmvifoo4f00mj7dnnu7hxisl0', 2, 'Parent-Teacher Meeting on 25 October', 'Parent-Teacher Meeting will be held on 25 October 2026 at 11:00 AM in the school premises. All parents are requested to attend the meeting and bring the student''s report card. For any queries, please contact the class teacher.', 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'cmvifoo2100ls7dnnkt3rtjg0', '2026-10-11 04:30:00'),
	('cmvifoomq00t47dnnyy81noy2', 'cmvifoomq00t37dnn1k46dolq', 1, 'Scholarship forms due 31 October', 'Scholarship forms for eligible students of Class 9 must be submitted at the school office on or before 31 October 2026. Please bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship amount is ₹5,000 per year. For help, call the school office at 90000 00001.', NULL, 'cmvifoo2400lu7dnnfzqbagpd', '2026-10-04 04:30:00'),
	('cmvifoon500t87dnni1kf5osy', 'cmvifoomq00t37dnn1k46dolq', 2, 'Scholarship forms due 31 October', 'Scholarship forms for eligible students of Class 9 must be submitted at the school office on or before 31 October 2026. Please bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship amount is ₹5,000 per year. For help, call the school office at 90000 00001.', 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', 'cmvifoo2400lu7dnnfzqbagpd', '2026-10-04 04:30:00'),
	('cmvifoovj00yl7dnnbxpq3bil', 'cmvifoovj00yk7dnnarijnb7r', 1, 'Diwali vacation dates', 'The school will remain closed from 9 November 2026 to 22 November 2026 for the Diwali vacation. Classes will resume on 23 November 2026.', NULL, 'cmvifoo2500lw7dnn42cz5uxg', '2026-09-28 04:30:00'),
	('cmvifoovw00yp7dnnrxamx4lh', 'cmvifoovj00yk7dnnarijnb7r', 2, 'Diwali vacation dates', 'The school will remain closed from 9 November 2026 to 22 November 2026 for the Diwali vacation. Classes will resume on 23 November 2026.', 'School is closed for the Diwali vacation from 9 November 2026 to 22 November 2026. School opens again on 23 November 2026.', 'cmvifoo2500lw7dnn42cz5uxg', '2026-09-28 04:30:00'),
	('cmvifoph301at7dnnk4kmjirk', 'cmvifoph201as7dnn9n8hnbb7', 1, 'Half-yearly examination timetable', 'The half-yearly examination for Classes 6 to 8 will begin on 3 November 2026. Examinations will start at 10:30 AM every day. Students must carry their hall ticket and arrive at school 15 minutes before the examination.', NULL, 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-17 04:30:00'),
