INSERT INTO "TranslationRevision" (id, "translationId", version, text, origin, provider, "createdById", "createdAt") VALUES
	('cmvifoo5g00mu7dnn97wgv1cy', 'cmvifoo5e00ms7dnnfixb6dsh', 1, 'વાલી-શિક્ષક બેઠક ૨૫ ઓક્ટોબર ૨૦૨૬ ના રોજ સવારે ૧૧:૦૦ વાગ્યે યોજાશે. બેઠક શાળાના પરિસરમાં થશે. કૃપા કરીને બેઠકમાં હાજર રહો. તમારા બાળકનું રિપોર્ટ કાર્ડ સાથે લાવવું. કોઈ પ્રશ્ન હોય તો વર્ગ શિક્ષકનો સંપર્ક કરો.', 'generated', 'demo', 'cmvifoo2100ls7dnnkt3rtjg0', '2026-10-21 18:16:38.98'),
	('cmvifoo6000n47dnnzouc775s', 'cmvifoo5z00n27dnniekpl3ux', 1, 'अभिभावक-शिक्षक बैठक 25 अक्टूबर 2026 को सुबह 11:00 बजे होगी। बैठक विद्यालय परिसर में होगी। कृपया बैठक में आएं। अपने बच्चे का रिपोर्ट कार्ड साथ लाएं। कोई सवाल हो तो कक्षा शिक्षक से संपर्क करें।', 'generated', 'demo', 'cmvifoo2100ls7dnnkt3rtjg0', '2026-10-21 18:16:39.001'),
	('cmvifoo6l00ne7dnn4372cn1u', 'cmvifoo6k00nc7dnn2y5a6hcm', 1, 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'generated', 'demo', 'cmvifoo2100ls7dnnkt3rtjg0', '2026-10-21 18:16:39.021'),
	('cmvifoong00te7dnnou3uuskw', 'cmvifoonf00tc7dnn6r5kb3fr', 1, 'ધોરણ ૯ ના પાત્ર વિદ્યાર્થીઓ શિષ્યવૃત્તિ માટે અરજી કરી શકે છે. ફોર્મ ૩૧ ઓક્ટોબર ૨૦૨૬ સુધીમાં શાળા કાર્યાલયમાં જમા કરાવો. વિદ્યાર્થીનું આધાર કાર્ડ, બેંક પાસબુક અને આવકનો દાખલો સાથે લાવો. શિષ્યવૃત્તિ દર વર્ષે ₹૫,૦૦૦ છે. મદદ માટે શાળા કાર્યાલયને ૯૦૦૦૦ ૦૦૦૦૧ પર ફોન કરો.', 'generated', 'demo', 'cmvifoo2400lu7dnnfzqbagpd', '2026-10-21 18:16:39.628'),
	('cmvifooo100to7dnn2uizirg7', 'cmvifooo000tm7dnnhy0a7jxq', 1, 'कक्षा 9 के पात्र विद्यार्थी छात्रवृत्ति के लिए आवेदन कर सकते हैं। फॉर्म 31 अक्टूबर 2026 तक विद्यालय कार्यालय में जमा करें। विद्यार्थी का आधार कार्ड, बैंक पासबुक और आय प्रमाण पत्र साथ लाएं। छात्रवृत्ति ₹5,000 प्रति वर्ष है। मदद के लिए विद्यालय कार्यालय को 90000 00001 पर फ़ोन करें।', 'generated', 'demo', 'cmvifoo2400lu7dnnfzqbagpd', '2026-10-21 18:16:39.649'),
	('cmvifooom00ty7dnnz8mpc3do', 'cmvifoook00tw7dnn391lsllu', 1, 'Eligible Class 9 students can apply for a scholarship. Submit the form at the school office by 31 October 2026. Bring the student''s Aadhaar card, bank passbook and income certificate. The scholarship is ₹5,000 per year. For help, call the school office at 90000 00001.', 'generated', 'demo', 'cmvifoo2400lu7dnnfzqbagpd', '2026-10-21 18:16:39.671'),
	('cmvifoow600yv7dnn0iqk2kq7', 'cmvifoow500yt7dnnnpwqvydn', 1, 'દિવાળી વેકેશન માટે શાળા ૯ નવેમ્બર ૨૦૨૬ થી ૨૨ નવેમ્બર ૨૦૨૬ સુધી બંધ રહેશે. શાળા ૨૩ નવેમ્બર ૨૦૨૬ ના રોજ ફરી શરૂ થશે.', 'generated', 'demo', 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-21 18:16:39.942'),
	('cmvifoowk00z57dnnbcvnylr6', 'cmvifoowj00z37dnn6gkgsaba', 1, 'दीवाली अवकाश के लिए विद्यालय 9 नवंबर 2026 से 22 नवंबर 2026 तक बंद रहेगा। विद्यालय 23 नवंबर 2026 को फिर से खुलेगा।', 'generated', 'demo', 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-21 18:16:39.957'),
	('cmvifoowy00zf7dnneb67lmsb', 'cmvifoowx00zd7dnnxcn1vjcm', 1, 'School is closed for the Diwali vacation from 9 November 2026 to 22 November 2026. School opens again on 23 November 2026.', 'generated', 'demo', 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-21 18:16:39.97'),
	('cmvifophs01b37dnnkzx6o072', 'cmvifophr01b17dnne0daacjh', 1, 'ધોરણ ૬ થી ૮ ની છમાસિક પરીક્ષા ૩ નવેમ્બર ૨૦૨૬ થી શરૂ થશે. દરરોજ પરીક્ષા સવારે ૧૦:૩૦ વાગ્યે શરૂ થશે. વિદ્યાર્થીઓએ હોલ ટિકિટ સાથે લાવવી. વિદ્યાર્થીઓ પરીક્ષાના ૧૫ મિનિટ પહેલાં શાળામાં આવો.', 'generated', 'demo', 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-21 18:16:40.72'),
	('cmvifopi601bd7dnndnc2zu0b', 'cmvifopi501bb7dnnbewzyb7n', 1, 'कक्षा 6 से 8 की अर्धवार्षिक परीक्षा 3 नवंबर 2026 से शुरू होगी। हर दिन परीक्षा सुबह 10:30 बजे शुरू होगी। विद्यार्थी अपना प्रवेश पत्र साथ लाएं। विद्यार्थी परीक्षा से 15 मिनट पहले विद्यालय में आएं।', 'generated', 'demo', 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-21 18:16:40.734'),
	('cmvifopil01bn7dnngcyra5wf', 'cmvifopik01bl7dnnnc424je2', 1, 'The half-yearly exam for Classes 6 to 8 starts on 3 November 2026. Each exam starts at 10:30 AM. Students must bring their hall ticket. Students should come to school 15 minutes early.', 'generated', 'demo', 'cmvifoo2500lw7dnn42cz5uxg', '2026-10-21 18:16:40.75'),
	('cmvifopmf01e47dnn3k8me6ur', 'cmvifopme01e27dnnje4qoghs', 1, 'વાલી-શિક્ષક બેઠક ૨૫ ઓક્ટોબર ૨૦૨૬ ના રોજ સવારે ૧૧:૦૦ વાગ્યે યોજાશે. બેઠક શાળાના પરિસરમાં થશે. કૃપા કરીને બેઠકમાં હાજર રહો. તમારા બાળકનું રિપોર્ટ કાર્ડ સાથે લાવવું. કોઈ પ્રશ્ન હોય તો વર્ગ શિક્ષકનો સંપર્ક કરો.', 'generated', 'demo', 'cmvifoo2100ls7dnnkt3rtjg0', '2026-10-21 18:16:40.887'),
