	('cmvifoqab01vs7dnnm3ymk71o', 'cmvifoqa901vq7dnnxjwfnqib', 1, 'There is a Parent-Teacher Meeting on 25 October 2026 at 11:00 AM. It will be in the school premises. Please come to the meeting. Please bring your child''s report card. If you have a question, please contact the class teacher.', 'generated', 'demo', 'cmvifoo2q00m57dnnzexuicmw', '2026-10-21 18:16:41.747'),
	('cmvifoql502257dnn43rapj8r', 'cmvifoql402237dnnse2ohu0p', 1, 'ધોરણ ૯ ના પાત્ર વિદ્યાર્થીઓ શિષ્યવૃત્તિ માટે અરજી કરી શકે છે. ફોર્મ ૩૧ ઓક્ટોબર ૨૦૨૬ સુધીમાં શાળા કાર્યાલયમાં જમા કરાવો. વિદ્યાર્થીનું આધાર કાર્ડ, બેંક પાસબુક અને આવકનો દાખલો સાથે લાવો. શિષ્યવૃત્તિ દર વર્ષે ₹૫,૦૦૦ છે. મદદ માટે શાળા કાર્યાલયને ૯૦૦૦૦ ૦૦૦૦૧ પર ફોન કરો.', 'generated', 'demo', 'cmvifoo2q00m57dnnzexuicmw', '2026-10-21 18:16:42.137'),
	('cmvifoqlj022f7dnn5aejvr8p', 'cmvifoqli022d7dnnftlys513', 1, 'कक्षा 9 के पात्र विद्यार्थी छात्रवृत्ति के लिए आवेदन कर सकते हैं। फॉर्म 31 अक्टूबर 2026 तक विद्यालय कार्यालय में जमा करें। विद्यार्थी का आधार कार्ड, बैंक पासबुक और आय प्रमाण पत्र साथ लाएं। छात्रवृत्ति ₹5,000 प्रति वर्ष है। मदद के लिए विद्यालय कार्यालय को 90000 00001 पर फ़ोन करें।', 'generated', 'demo', 'cmvifoo2q00m57dnnzexuicmw', '2026-10-21 18:16:42.151'),
